def make_output(d, marker_colors, marker_by_input):
    templ={}
    for start in [0,4,8]:
        vals=[v for row in d[:3] for v in row[start:start+3] if v and v!=5]
        color=vals[0]
        pat=[[marker_by_input[color] if x==color else 0 for x in row[start:start+3]] for row in d[:3]]
        templ[color]=pat
    board=[[None]*3 for _ in range(3)]
    for y in range(3):
        for start in [0,4,8]:
            for dx in range(3):
                v=d[4+y][start+dx]
                if v and v!=5:
                    board[y][dx]=templ[v]
    out=[]
    for y in range(3):
        for py in range(3):
            out.append(sum([board[y][x][py] if board[y][x] is not None else [0]*3 for x in range(3)],[]))
    return out, board, templ
